import unittest

from web import export


class TestExport(unittest.TestCase):
    def test_rows(self):
        out = export.export([{"ts": "2026-10-01T09:00:00", "sensor": "a1", "temp": 20.0}])
        self.assertEqual(out["rows"], ["2026-10-01T09:00:00Z a1 20.0 °C"])

    def test_no_note_when_nothing_was_skipped(self):
        out = export.export([{"ts": "2026-10-01T09:00:00", "sensor": "a1", "temp": 20.0}])
        self.assertEqual(out["skipped"], 0)
        self.assertNotIn("note", out)

    def test_skips_readings_without_temp_and_says_so(self):
        out = export.export([
            {"ts": "2026-10-01T09:00:00", "sensor": "a1", "temp": 20.0},
            {"ts": "2026-10-01T09:05:00", "sensor": "a2", "temp": None},
            {"ts": "2026-10-01T09:10:00", "sensor": "a3", "temp": None},
        ])
        self.assertEqual(out["rows"], ["2026-10-01T09:00:00Z a1 20.0 °C"])
        self.assertEqual(out["skipped"], 2)
        self.assertEqual(out["note"], "2 readings skipped (no temperature)")

    def test_since_drops_older_readings_without_counting_them(self):
        out = export.export([
            {"ts": "2026-09-30T23:59:00", "sensor": "a1", "temp": None},
            {"ts": "2026-10-01T09:00:00", "sensor": "a2", "temp": 20.0},
        ], since="2026-10-01")
        self.assertEqual(out["rows"], ["2026-10-01T09:00:00Z a2 20.0 °C"])
        self.assertEqual(out["skipped"], 0)
        self.assertNotIn("note", out)

    def test_since_rejects_a_day_that_is_not_yyyy_mm_dd(self):
        with self.assertRaises(ValueError):
            export.export([], since="2026-10-01T09:00:00")

